{
  "avaliacoes": [
    {
      "id": "Eefd24671a2e3ab19",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A operação do flare deve prever arranjos de purga, tipicamente com nitrogênio ou gás combustível, para impedir entrada de ar nos headers e evitar formação de mistura inflamável, inclusive em condições de partida e parada quando pode não haver gás combustível disponível.",
          "trechos": [
            "Eefd24671a2e3ab19:0:692"
          ],
          "condicoes": [
            "Aplicável à operação do flare e à prevenção de mistura inflamável nos headers",
            "A própria fonte destaca condições de partida e parada"
          ],
          "limites": [
            "A fonte é orientação de autoridade estrangeira e não deve ser convertida automaticamente em requisito brasileiro",
            "Não define taxa de purga nem solução única de projeto"
          ]
        },
        {
          "proposicao": "Após parada da plataforma com extinção da tocha, os procedimentos operacionais devem orientar a reignição somente após purga do trecho entre o knock-out drum e a ponta para remoção de ar, com definição de taxa mínima e duração da purga.",
          "trechos": [
            "Eefd24671a2e3ab19:692:1392"
          ],
          "condicoes": [
            "Aplicável após shutdown que apague o flare",
            "Depende de procedimento operacional para reignição"
          ],
          "limites": [
            "Os valores de taxa mínima e duração não são fornecidos no trecho",
            "O trecho não demonstra validação experimental nem substitui procedimento específico da instalação"
          ]
        },
        {
          "proposicao": "A ignição do flare deve usar meio seguro, com preferência por sistema de ignição engenheirado; quando esse sistema não existir ou estiver indisponível, deve haver meio alternativo seguro e método para manter conteúdo da chaminé e pilotos fora da faixa inflamável a fim de evitar flashback durante o acendimento.",
          "trechos": [
            "Eefd24671a2e3ab19:1392:2088"
          ],
          "condicoes": [
            "Aplicável ao momento de acendimento do flare",
            "A prevenção de flashback é vinculada à condição de mistura fora da região inflamável"
          ],
          "limites": [
            "A fonte não detalha arquitetura, redundância ou teste funcional do sistema de ignição",
            "A preferência por sistema engenheirado é orientação técnica, não obrigação geral demonstrada para FPSO no Brasil"
          ]
        }
      ]
    },
    {
      "id": "Ea8012ea844fa2b6f",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em fluxos baixos ou sem purga, a chaminé pode ficar com pressão negativa na base por efeito da tiragem do gás residual, permitindo entrada de ar por vazamentos em conexões, flanges ou tampas e formando mistura explosiva interna.",
          "trechos": [
            "Ea8012ea844fa2b6f:0:699"
          ],
          "condicoes": [
            "Associado a gás residual de baixa densidade, baixo peso molecular ou temperatura elevada",
            "Associado também a taxas muito baixas de purga"
          ],
          "limites": [
            "A fonte não quantifica a condição de pressão negativa nem a taxa de purga necessária",
            "Documento sem fronteiras documentais claras, exigindo cautela na generalização"
          ]
        },
        {
          "proposicao": "A segurança da operação da tocha é apresentada como dependente da ausência de ar-oxigênio nos gases até a chegada aos pilotos; por isso, usa-se purga para evitar entrada de ar enquanto a tocha estiver em operação e os pilotos estiverem acesos.",
          "trechos": [
            "Ea8012ea844fa2b6f:699:1399"
          ],
          "condicoes": [
            "Aplicável à operação com pilotos acesos",
            "A proposição é apresentada como comentário geral de segurança"
          ],
          "limites": [
            "Não informa critério de suficiência da purga",
            "Não trata de intertravamentos, monitoração de chama ou comprovação de estanqueidade"
          ]
        },
        {
          "proposicao": "Se for necessário abrir o sistema, a fonte orienta apagar os pilotos antes do início do trabalho e só reacendê-los depois de o sistema estar completamente purgado; também descreve selo molecular como arranjo para evitar entrada de ar com menor consumo de gás de selagem, baseado na diferença de peso molecular e em reposição contínua de gás mais leve que o ar.",
          "trechos": [
            "Ea8012ea844fa2b6f:699:1399",
            "Ea8012ea844fa2b6f:1399:2018"
          ],
          "condicoes": [
            "A orientação operacional vale quando o sistema precisa ser aberto para intervenção",
            "A descrição do selo molecular depende de manutenção de pressão sobre-atmosférica por reposição contínua"
          ],
          "limites": [
            "A fonte não compara o selo molecular com outras alternativas de vedação",
            "Não há critérios de seleção, dimensionamento ou desempenho mínimo do selo"
          ]
        }
      ]
    },
    {
      "id": "E02e8c3c91e09b2a1",
      "pertinente": false,
      "tipo": "recomendacao",
      "achados": []
    },
    {
      "id": "Ef059491884f46cf2",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Potes de selo, loops de selo e selos tipo lute em sistemas de drenagem são descritos como meios de segregação entre sistemas, mantendo selo líquido para impedir migração de gás.",
          "trechos": [
            "Ef059491884f46cf2:0:687",
            "Ef059491884f46cf2:687:1385"
          ],
          "condicoes": [
            "Aplicável a sistemas de drenagem interligados e segregação entre correntes perigosas e não perigosas",
            "O selo depende de permanecer cheio de líquido"
          ],
          "limites": [
            "O foco principal é drenagem, não header de flare",
            "A utilidade para o recorte é indireta, por analogia de função de selo e prevenção de migração"
          ]
        },
        {
          "proposicao": "A integridade e efetividade dos selos líquidos dependem de inspeções rotineiras para verificar selos intactos, ausência de detritos que bloqueiem drenos e presença de respiros ou quebradores de sifão em quedas verticais para evitar esvaziamento do selo.",
          "trechos": [
            "Ef059491884f46cf2:0:687"
          ],
          "condicoes": [
            "Aplicável quando a segregação entre sistemas depende de selo líquido",
            "Inclui risco de perda do selo por sifonamento e bloqueio por detritos"
          ],
          "limites": [
            "Não apresenta frequência de inspeção nem critérios quantitativos de aceitação",
            "Não trata diretamente de ignição, pilotos ou retorno de chama no flare"
          ]
        },
        {
          "proposicao": "Onde vasos de drenagem perigosos ventilam para a atmosfera, a fonte recomenda facilidades de purga para prevenir entrada de ar; também recomenda proteção contra congelamento e bloqueio de linhas e loops de selo.",
          "trechos": [
            "Ef059491884f46cf2:1385:2074",
            "Ef059491884f46cf2:2074:2182"
          ],
          "condicoes": [
            "Aplicável a vasos de drenagem com ventilação atmosférica",
            "Particularmente relevante em contextos com risco de congelamento"
          ],
          "limites": [
            "Trata-se de orientação para drenagem em instalação offshore, não critério específico de flare em FPSO",
            "A referência de winterisation reflete contexto operacional específico e não requisito universal"
          ]
        }
      ]
    },
    {
      "id": "Efdfe9a69b4091453",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Após shutdowns ou períodos em que o flare estiver apagado, deve haver provisão para purga dos headers a fim de deslocar o ar e eliminar o risco de atmosfera inflamável antes da ignição.",
          "trechos": [
            "Efdfe9a69b4091453:0:700"
          ],
          "condicoes": [
            "Aplicável após parada ou extinção do flare",
            "A finalidade declarada é remover ar antes da ignição"
          ],
          "limites": [
            "A fonte não detalha como comprovar a eliminação total do risco no header do flare",
            "É orientação de fonte estrangeira, não requisito brasileiro demonstrado"
          ]
        },
        {
          "proposicao": "Gás de processo pode ser usado para purga do flare antes da partida, desde que tenha taxa e volume suficientes para produzir purga efetiva; combustível ou nitrogênio também podem ser usados em alguns tanques e vasos para manter pressurização do sistema, acomodar expansão e contração ou excluir ar.",
          "trechos": [
            "Efdfe9a69b4091453:0:700"
          ],
          "condicoes": [
            "Aplicável à purga pré-partida do flare",
            "O uso de gás de processo é condicionado à suficiência de taxa e volume"
          ],
          "limites": [
            "O trecho não estabelece método de cálculo nem valores de suficiência",
            "A extensão para todos os tipos de vasos e sistemas não deve ser presumida"
          ]
        },
        {
          "proposicao": "Em manutenção e retorno ao serviço, a fonte recomenda controlar atmosferas inflamáveis por purga com nitrogênio ou outro gás inerte e amostragem posterior da atmosfera inerte; para casos de hidrocarboneto não totalmente removível em tanques ou caixões abertos, podem ser necessárias precauções especiais como purga contínua ou colchão de espuma.",
          "trechos": [
            "Efdfe9a69b4091453:700:1398",
            "Efdfe9a69b4091453:1398:2096"
          ],
          "condicoes": [
            "Aplicável a intervenções de manutenção e retorno ao serviço",
            "As precauções especiais são condicionadas à impossibilidade de remoção completa do hidrocarboneto"
          ],
          "limites": [
            "O valor típico de oxigênio citado na fonte pertence a orientação estrangeira e não deve ser tratado como limite normativo brasileiro sem base específica",
            "O trecho trata de controle de atmosfera em manutenção de forma geral, não apenas de flare"
          ]
        }
      ]
    },
    {
      "id": "Ee706269dd09d96e3",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A escolha da altura e da localização das chaminés de flare deve considerar segurança do pessoal e dos equipamentos frente à radiação térmica de uma chama de grande porte.",
          "trechos": [
            "Ee706269dd09d96e3:699:1395",
            "Ee706269dd09d96e3:1395:2010"
          ],
          "condicoes": [
            "Apresentado no contexto de projeto de sistema de flare",
            "A análise é motivada por cenário acidental de grandes proporções"
          ],
          "limites": [
            "Os valores numéricos do trecho estão apagados e não podem ser reconstruídos",
            "O trecho não trata diretamente de pilotos, purga, selos ou retorno de chama"
          ]
        },
        {
          "proposicao": "Quando uma altura de chaminé suficiente for impraticável para atender à condição de segurança térmica pretendida, a fonte recomenda adoção de medidas de proteção adequadas para proteger pessoas.",
          "trechos": [
            "Ee706269dd09d96e3:1395:2010"
          ],
          "condicoes": [
            "Aplicável quando a solução geométrica por altura não for praticável",
            "Vinculado à proteção de pessoas expostas em cenário acidental"
          ],
          "limites": [
            "A fonte não especifica quais medidas de proteção devem ser adotadas",
            "A utilidade para o recorte é periférica, mais ligada à implantação do flare"
          ]
        }
      ]
    }
